where
    grass_region in (${grass_region})
    and local_date = ${local_date}
    and is_assignment_log = 1
    and scene_id in (142, 373, 132, 368, 1718, 1605, 2065)
    -- daily_discover_main: 142; global_priority: 373; product_detail_page: 132;
    -- cart_unify: 368; rcmd_ddpp_merge: 2065
;

