create temporary view user_cluster_agg_${grass_region_without_quote} as
select
    user_id
    ,item_llm_cluster_id
    ,'Aggregated Organic Item' as card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt
from
    user_item_union_${grass_region_without_quote}
where
    target_type in ('item', 'item_mix_feed_card')
    and is_ads != 'true'
group by 1, 2, 4

union all -- Aggregated Item
select
    user_id
    ,item_llm_cluster_id
    ,'Aggregated Item' as card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt
from
    user_item_union_${grass_region_without_quote}
where
    target_type in ('item', 'item_mix_feed_card')
group by 1, 2, 4

union all -- Aggregated Video
select
    user_id
    ,item_llm_cluster_id
    ,'Aggregated Video' as card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt
from
    user_item_union_${grass_region_without_quote}
where
    target_type = 'video'
    and (scene_type in ('DD', 'PP') or scene_type like 'PP - %')
group by 1, 2, 4

union all -- Aggregated Item + Video
select
    user_id
    ,case
        when item_llm_cluster_id is null then null
        when target_type = 'video' then concat('v#', item_llm_cluster_id)
        else item_llm_cluster_id
    end as item_llm_cluster_id
    ,'Aggregated Item + Video' as card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt
from
    user_item_union_${grass_region_without_quote}
where
    target_type in ('item', 'item_mix_feed_card', 'video')
    and (scene_type in ('DD', 'PP') or scene_type like 'PP - %')
group by 1, 2, 4
;

