    ,count(distinct case when omni_scenario_click_cnt > 0 then item_llm_cluster_id else null end) as click_llm_cat_count_per_uu
    ,count(distinct case when order_cnt > 0 then item_llm_cluster_id else null end) as order_llm_cat_count_per_uu
from
    user_cluster_exp_${grass_region_without_quote}
where
    scene_type in ('DD', 'PP', 'Search', 'YMAL')
    and card_type not in ('Aggregated Video', 'Aggregated Item + Video')
group by 1, 2, 3

union all
select
    user_id
    ,exp_group_id
    ,card_type
    ,scene_type
    ,sum(omni_scenario_imp_cnt)   as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    ,sum(order_cnt) as order_cnt

    ,count(distinct case when omni_scenario_imp_cnt > 0 then item_llm_cluster_id else null end) as imp_llm_cat_count_per_uu
    ,count(distinct case when omni_scenario_click_cnt > 0 then item_llm_cluster_id else null end) as click_llm_cat_count_per_uu
    ,count(distinct case when order_cnt > 0 then item_llm_cluster_id else null end) as order_llm_cat_count_per_uu
from
    user_cluster_exp_${grass_region_without_quote}
where
